<?php
 namespace QQWorld\Setup\Module\Dependency; use QQWorld\Framework\Data\Graph; class Circular { protected $dependencies = []; protected $circularDependencies = []; protected $graph; public function buildCircularDependencies($dependencies) { $this->init($dependencies); foreach (array_keys($this->dependencies) as $vertex) { $this->expandDependencies($vertex); } $circulars = $this->graph->findCycle(null, false); foreach ($circulars as $circular) { array_shift($circular); $this->buildCircular($circular); } return $this->divideByModules($this->circularDependencies); } protected function init($dependencies) { $this->dependencies = $dependencies; $this->circularDependencies = []; $this->graph = new Graph(array_keys($this->dependencies), []); } protected function expandDependencies($vertex, $path = []) { if (!$this->dependencies[$vertex]) { return; } $path[] = $vertex; foreach ($this->dependencies[$vertex] as $dependency) { if (!isset($this->dependencies[$dependency])) { continue; } $relations = $this->graph->getRelations(); if (isset($relations[$vertex][$dependency])) { continue; } $this->graph->addRelation($vertex, $dependency); $searchResult = array_search($dependency, $path); if (false !== $searchResult) { $this->buildCircular(array_slice($path, $searchResult)); break; } else { $this->expandDependencies($dependency, $path); } } } protected function buildCircular($modules) { $path = '/' . implode('/', $modules); if (isset($this->circularDependencies[$path])) { return; } $this->circularDependencies[$path] = $modules; array_push($modules, array_shift($modules)); $this->buildCircular($modules); } protected function divideByModules($circularDependencies) { $dependenciesByModule = []; foreach ($circularDependencies as $circularDependency) { $module = $circularDependency[0]; array_push($circularDependency, $module); $dependenciesByModule[$module][] = $circularDependency; } return $dependenciesByModule; } } 